// Bancos de los demás cursos (se unen al de Matemática en banco_preguntas.php).
// Cada curso tiene 4 ramas; cada rama: 4 consejos (niveles 1-4) y 12 preguntas
// (3 por nivel del 1 al 4; el examen del nivel 5 toma 10 al azar).

function st_rama(string $nombre, array $consejos, array $preguntas): array
{
    return ['nombre' => $nombre, 'consejos' => array_combine([1, 2, 3, 4], $consejos), 'preguntas' => $preguntas];
}

